pub struct MissingCred;
pub struct MissingSecret(String);
pub struct MissingKey(String);
pub struct Complete {
    key: String,
    secret: String,
}

pub struct Builder<State> {
    addr: Url,
    region: Option<String>,
    cred: State,
    url_style: Option<UrlStyle>,
    token: [REDACTED],
    actions_expires_in: Option<Duration>,
    timeout: Option<Duration>,
    multipart_size: Option<usize>,
}

impl Builder<MissingCred> {
    /// Create a new `Builder`.
    /// It's currently missing its key and secret.
    ///
    /// # Example
    /// ```
    /// use strois::Builder;
    ///
    /// let client = Builder::new("http://localhost:9000")?
    ///     .key("minioadmin")
    ///     .secret("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    /// If you try to call `.client()` before setting the key and secret it won't work.
    /// ```compile_fail
    /// use strois::Builder;
    ///
    /// let client = Builder::new("http://localhost:9000")?
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    /// But if you only forgot the secret it should panic as well:
    /// ```compile_fail
    /// use strois::Builder;
    ///
    /// let client = Builder::new("http://localhost:9000")?
    ///     .secret("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    /// Same for the key:
    /// ```compile_fail
    /// use strois::Builder;
    ///
    /// let client = Builder::new("http://localhost:9000")?
    ///     .key("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    pub fn new(addr: impl AsRef<str>) -> Result<Self> {
        Ok(Self {
            addr: addr.as_ref().parse()?,
            region: None,
            cred: MissingCred,
            url_style: None,
            token: None,
            actions_expires_in: None,
            timeout: None,
            multipart_size: None,
        })
    }

    /// Create a new `Builder` based on an AWS region
    /// It's currently missing its key and secret.
    ///
    /// # Example
    /// ```
    /// use strois::Builder;
    ///
    /// let client = Builder::new_region(awsregion::Region::UsEast1)
    ///     .key("minioadmin")
    ///     .secret("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    /// If you try to call `.client()` before setting the key and secret it won't work.
    /// ```compile_fail
    /// use strois::Builder;
    ///
    /// let client = Builder::new_region(awsregion::Region::UsEast1)
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    /// But if you only forgot the secret it should panic as well:
    /// ```compile_fail
    /// use strois::Builder;
    ///
    /// let client = Builder::new_region(awsregion::Region::UsEast1)
    ///     .secret("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    /// Same for the key:
    /// ```compile_fail
    /// use strois::Builder;
    ///
    /// let client = Builder::new_region(awsregion::Region::UsEast1)
    ///     .key("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    ///
    #[cfg(feature="aws-region")]
    pub fn new_region(region: awsregion::Region) -> Self {
        Self {
            addr: format!("{}://{}", region.scheme(), region.endpoint()).parse().unwrap(),
            region: Some(region.to_string()),
            cred: MissingCred,
            url_style: None,
            token: None,
            actions_expires_in: None,
            timeout: None,
            multipart_size: None,
        }
    }

    /// Set the key in the `Builder`.
    ///
    /// # Example
    /// ```
    /// use strois::Builder;
    ///
    /// let client = Builder::new("http://localhost:9000")?
    ///     .key("minioadmin")
    ///     .secret("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    pub fn key(self, key: impl Into<String>) -> Builder<MissingSecret> {
        Builder {
            addr: self.addr,
            region: self.region,
            cred: MissingSecret(key.into()),
            url_style: None,
            token: self.token,
            actions_expires_in: self.actions_expires_in,
            timeout: self.timeout,
            multipart_size: None,
        }
    }

    /// Set the secret in the `Builder`.
    ///
    /// # Example
    /// ```
    /// use strois::Builder;
    ///
    /// let client = Builder::new("http://localhost:9000")?
    ///     .secret("minioadmin")
    ///     .key("minioadmin")
    ///     .client();
    /// # Ok::<(), strois::Error>(())
    /// ```
    pub fn secret(self, secret: impl Into<String>) -> Builder<MissingKey> {
        Builder {
            addr: self.addr,
            region: self.region,
            cred: MissingKey(secret.into()),
            url_style: None,
            token: self.token,
            actions_expires_in: self.actions_expires_in,
            timeout: self.timeout,
            multipart_size: None,
        }
    }
}

